# Auxiliary function: Perform linear interpolation for floating-point values.def _interpolate_float(x_min: int, y_min: float,                        x_max: int, y_max: float,                        x: int) -> float:    # Compute the slop of the straight line connecting (x_min, y_min) and (x_max, y_max).    slope = (y_max - y_min) / (x_max - x_min)    # Return the y coordinate on this line for the given x value.    y = y_min + slope * (x - x_min)    return y# Auxiliary function: Perform linear interpolation for integer values.def _interpolate_int(x_min: int, y_min: int,                        x_max: int, y_max: int,                        x: int) -> float:    # Perform linear interpolation and find the real value for y.    y = _interpolate_float(x_min, float(y_min),                           x_max, float(y_max),                           x)    # Round to the nearest integer.    return int(y + 0.5)class VadParameters:    """    Parameters for the VAD algorithm.        Fields    ------        sampling_rate: float        The signal sampling rate, in Hz.            window_size: int        The number of samples in each spectrogram window.            window_slide: int        The number of samples between each two consecutive frames.            max_inactive_probability: float        The maximal probability for classifying a frame as inactive (i.e. if the activity probability of the frame        is below this threshold, it is classified as an inactive frame).    min_active_probability: float        The minimal probability for classifying a frame as active (i.e. if the activity probability of the frame        is above this threshold, it is classified as an active frame).        min_active_frames: int        The minimal number of consecutive frames that need to be classified as active before the start of an active        segment is detected.        min_inactive_frames: int        The minimal number of consecutive frames that need to be classified as inactive before the end of an active        segment is detected.        min_segment_frames: int         Minimal number of frames in a valid segment; segments with fewer frames are discarded.    margin_frames: int        The number of margin frames to add from each side of a valid active segment.        max_segment_frames: int        The maximal number of frames in an active segment; longer segments are subdivided into subsegments.        alpha_power: float         Smoothing factor for the power values.        boost_environment_size: int          Environment size for smoothing and boosting computed probabilities.        interval_size: int          Number of frames in each power-estimation interval.        """    __offline_vad_low_max_inactive_prob = 0.25    __offline_vad_low_min_active_prob = 0.45    __offline_vad_low_min_active_frames = 12    __offline_vad_low_min_segment_frames = 40    __offline_vad_low_boost_environment_size = 1        __offline_vad_high_max_inactive_prob = 0.15    __offline_vad_high_min_active_prob = 0.35    __offline_vad_high_min_active_frames = 8    __offline_vad_high_min_segment_frames = 20    __offline_vad_high_boost_environment_size = 5        __offline_vad_frag_min_inactive_frames = 12    __offline_vad_frag_margin_frames = 20    __offline_vad_frag_alpha_power = 0.56        __offline_vad_cont_min_inactive_frames = 28    __offline_vad_cont_margin_frames = 30    __offline_vad_cont_alpha_power = 0.64        __offline_vad_max_segment_frames = 4000    __offline_vad_estimator_interval_size = 3000        def __init__(self, sampling_rate: float, sensitivity_level: int = 3, segmentation_level: int = 3):        """        Constrcutor.                Parameters        ----------                sampling_rate : float            The sampling rate, in Hz.                    sensitivity_level : int            The VAD sensitivity level, ranging between 1 (low sensitivity) to 5 (high sensitivity).            Optional, the default sensitivity level is 3.                    segmentation_level : int            The VAD fragmentation level, ranging between 1 (prefer shorter, fragmented segments) to 5 (prefer longer, continuous segments).            Optional, the default segmentation level is 3.        """        self.sampling_rate = sampling_rate                self.window_size = int(sampling_rate * 0.025 + 0.5)        self.window_slide = int(sampling_rate * 0.01 + 0.5)                low_level = 1        high_level = 5        sense_level = max(min(sensitivity_level, high_level), low_level)        frag_mode = 1        cont_mode = 5        seg_mode = max(min(segmentation_level, cont_mode), frag_mode)        self.max_inactive_probability = _interpolate_float(low_level, VadParameters.__offline_vad_low_max_inactive_prob,                                                           high_level, VadParameters.__offline_vad_high_max_inactive_prob,                                                           sense_level)        self.min_active_probability = _interpolate_float(low_level, VadParameters.__offline_vad_low_min_active_prob,                                                         high_level, VadParameters.__offline_vad_high_min_active_prob,                                                         sense_level)        self.min_active_frames = _interpolate_int(low_level, VadParameters.__offline_vad_low_min_active_frames,                                                  high_level, VadParameters.__offline_vad_high_min_active_frames,                                                  sense_level)        self.min_inactive_frames = _interpolate_int(frag_mode, VadParameters.__offline_vad_frag_min_inactive_frames,                                                    cont_mode, VadParameters.__offline_vad_cont_min_inactive_frames,                                                    seg_mode)        self.min_segment_frames = _interpolate_int(low_level, VadParameters.__offline_vad_low_min_segment_frames,                                                   high_level, VadParameters.__offline_vad_high_min_segment_frames,                                                   sense_level)        self.margin_frames = _interpolate_int(frag_mode, VadParameters.__offline_vad_frag_margin_frames,                                              cont_mode, VadParameters.__offline_vad_cont_margin_frames,                                              seg_mode)        self.max_segment_frames = VadParameters.__offline_vad_max_segment_frames        self.alpha_power = _interpolate_float(frag_mode, VadParameters.__offline_vad_frag_alpha_power,                                              cont_mode, VadParameters.__offline_vad_cont_alpha_power,                                              seg_mode)        self.boost_environment_size = _interpolate_int(low_level, VadParameters.__offline_vad_low_boost_environment_size,                                                       high_level, VadParameters.__offline_vad_high_boost_environment_size,                                                       sense_level)                self.interval_size = VadParameters.__offline_vad_estimator_interval_size    